                .imem_rdata(axm_rdata[c*64 +: 64]), .imem_rresp(axm_rresp[c*2 +: 2]), .imem_rlast(axm_rlast[c]),

                .dmem_awvalid(axm_awvalid[c+4]), .dmem_awready(axm_awready[c+4]), .dmem_awaddr(axm_awaddr[(c+4)*40 +: 40]), 
                .dmem_awlen(), .dmem_awsize(), .dmem_awburst(),
                .dmem_wvalid(axm_wvalid[c+4]), .dmem_wready(axm_wready[c+4]), .dmem_wdata(axm_wdata[(c+4)*64 +: 64]), 
                .dmem_wstrb(axm_wstrb[(c+4)*8 +: 8]), .dmem_wlast(axm_wlast[c+4]),
                .dmem_bvalid(axm_bvalid[c+4]), .dmem_bready(axm_bready[c+4]), .dmem_bresp(axm_bresp[(c+4)*2 +: 2]),
                
                .dmem_arvalid(axm_arvalid[c+4]), .dmem_arready(axm_arready[c+4]), .dmem_araddr(axm_araddr[(c+4)*40 +: 40]), 
                .dmem_arlen(), .dmem_arsize(), .dmem_arburst(), .dmem_arlock(),
                .dmem_rvalid(axm_rvalid[c+4]), .dmem_rready(axm_rready[c+4]), .dmem_rdata(axm_rdata[(c+4)*64 +: 64]), 
                .dmem_rresp(axm_rresp[(c+4)*2 +: 2]), .dmem_rlast(axm_rlast[c+4]),
                .snoop_valid(l2_snoop_valid[c]), .snoop_addr(l2_snoop_addr), .snoop_type(l2_snoop_type),
                .snoop_ack(l2_snoop_ack[c]), .snoop_data_valid(l2_snoop_data_valid[c]), .snoop_data(core_snoop_data[c]),
                .halt_req(dbg_halt_req[c]), .resume_req(dbg_resume_req[c]),
                .hart_halted(dbg_hart_halted[c]), .hart_running(dbg_hart_running[c])
            );
            assign axm_arid[c*4 +: 4] = c[3:0];
            assign axm_awid[(c+4)*4 +: 4] = c[3:0] + 4'd4;
            assign axm_arid[(c+4)*4 +: 4] = c[3:0] + 4'd4;
        end
    endgenerate

    // -------------------------------------------------------
    // Core 4 Monitor (RV64IMAC)
    // -------------------------------------------------------
    assign axm_awvalid[8] = 1'b0;
    assign axm_awaddr[8*40 +: 40] = 40'h0;
    assign axm_awid[8*4 +: 4] = 4'h8;
    assign axm_wvalid[8] = 1'b0;
    assign axm_wdata[8*64 +: 64] = 64'h0;
    assign axm_wstrb[8*8 +: 8] = 8'h0;
    assign axm_wlast[8] = 1'b0;
    assign axm_bready[8] = 1'b1;
    assign axm_arid[8*4 +: 4] = 4'h8;
    assign axm_awid[9*4 +: 4] = 4'h9;
    assign axm_arid[9*4 +: 4] = 4'h9;
    assign axm_rready[8] = 1'b1;

    rv_monitor_core #(.HART_ID(4)) u_monitor (
        .clk(clk), .rst_n(core_rst_n),
        .irq_m_ext(plic_targets[8]), .irq_m_timer(timer_irq[4]), .irq_m_soft(sw_irq[4]),
        
        .imem_arvalid(axm_arvalid[8]), .imem_arready(axm_arready[8]), .imem_araddr(axm_araddr[8*40 +: 40]),
        .imem_rvalid(axm_rvalid[8]), .imem_rdata(axm_rdata[8*64 +: 64]), .imem_rresp(axm_rresp[8*2 +: 2]),
        
        .dmem_awvalid(axm_awvalid[9]), .dmem_awready(axm_awready[9]), .dmem_awaddr(axm_awaddr[9*40 +: 40]),
        .dmem_awlen(), .dmem_awsize(), .dmem_awburst(),
        .dmem_wvalid(axm_wvalid[9]), .dmem_wready(axm_wready[9]), .dmem_wdata(axm_wdata[9*64 +: 64]),
        .dmem_wstrb(axm_wstrb[9*8 +: 8]), .dmem_wlast(axm_wlast[9]),
        .dmem_bvalid(axm_bvalid[9]), .dmem_bready(axm_bready[9]), .dmem_bresp(axm_bresp[9*2 +: 2]),
        
        .dmem_arvalid(axm_arvalid[9]), .dmem_arready(axm_arready[9]), .dmem_araddr(axm_araddr[9*40 +: 40]),
        .dmem_arlen(), .dmem_arsize(), .dmem_arburst(),
        .dmem_rvalid(axm_rvalid[9]), .dmem_rready(axm_rready[9]), .dmem_rdata(axm_rdata[9*64 +: 64]),
        .dmem_rlast(), .dmem_rresp(axm_rresp[9*2 +: 2]),
        .halt_req(dbg_halt_req[4]), .resume_req(dbg_resume_req[4]),
        .hart_halted(dbg_hart_halted[4]), .hart_running(dbg_hart_running[4])
    );

    // -------------------------------------------------------
    // RISC-V Debug Module (JTAG 0.13 DM)
    // -------------------------------------------------------
    rv_debug #(
        .NUM_HARTS(5),
        .PROGBUF_SIZE(16)
    ) u_debug (
        .clk(clk),
        .rst_n(rst_n),
        .tck(1'b0),
        .tms(1'b0),
        .tdi(1'b0),
        .tdo(),
        .halt_req(dbg_halt_req),
        .resume_req(dbg_resume_req),
        .hart_halted(dbg_hart_halted),
        .hart_running(dbg_hart_running),
        .hart_unavail(5'b0),
        .reg_sel(),
        .reg_wr(),
        .reg_wdata(),
        .reg_rdata(64'h0),
        .cmd_exec(),
        .cmd_done(1'b1),
        .cmd_err(1'b0),
        .sb_arvalid(), .sb_arready(1'b0), .sb_araddr(),
        .sb_rvalid(1'b0), .sb_rready(), .sb_rdata(64'h0), .sb_rresp(2'b0),
        .sb_awvalid(), .sb_awready(1'b0), .sb_awaddr(),
        .sb_wvalid(), .sb_wready(1'b0), .sb_wdata(), .sb_wstrb(), .sb_wlast(),
        .sb_bvalid(1'b0), .sb_bready()
    );

    // DDR4 static pin control
    assign ddr_reset_n = rst_n;
    assign ddr_odt     = 1'b0;
    assign ddr_act_n   = 1'b1;

    // -------------------------------------------------------
    // Memory Subsystem (Slave 0) — L2 Cache & DDR4 Controller
    // -------------------------------------------------------
    wire         l2_m_arvalid, l2_m_arready;
    wire [39:0]  l2_m_araddr;
    wire         l2_m_rvalid, l2_m_rready;
    wire [63:0]  l2_m_rdata;
    wire [1:0]   l2_m_rresp;
    wire         l2_m_awvalid, l2_m_awready;
    wire [39:0]  l2_m_awaddr;
    wire         l2_m_wvalid, l2_m_wready;
    wire [63:0]  l2_m_wdata;
    wire [7:0]   l2_m_wstrb;
    wire         l2_m_bvalid, l2_m_bready;
    wire [1:0]   l2_m_bresp;

    // Crossbar Slave 0 ID tracking
    reg [3:0] l2_s_rid, l2_s_bid;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            l2_s_rid <= 4'h0;
            l2_s_bid <= 4'h0;
        end else begin
            if (axs_arvalid[0] && axs_arready[0])
                l2_s_rid <= axs_arid[0*4 +: 4];
            if (axs_awvalid[0] && axs_awready[0])
                l2_s_bid <= axs_awid[0*4 +: 4];
        end
    end
    assign axs_rlast[0]        = 1'b1;
    assign axs_rid[0*4 +: 4]   = l2_s_rid;
    assign axs_bid[0*4 +: 4]   = l2_s_bid;

    wire [511:0] l2_snoop_data_mux = l2_snoop_data_valid[0] ? core_snoop_data[0] :
                                     l2_snoop_data_valid[1] ? core_snoop_data[1] :
                                     l2_snoop_data_valid[2] ? core_snoop_data[2] :
                                     l2_snoop_data_valid[3] ? core_snoop_data[3] : 512'h0;

    l2_cache_top #(
        .WAYS(`L2_WAYS),
        .SETS(`L2_SETS)
    ) u_l2_cache (
        .clk(clk),
        .rst_n(rst_n),
        // Slave face (from crossbar Slave 0)
        .s_arvalid(axs_arvalid[0]),
        .s_arready(axs_arready[0]),
        .s_araddr (axs_araddr[0*40 +: 40]),
        .s_arid   (axs_arid[0*4 +: 4]),
        .s_rvalid (axs_rvalid[0]),
        .s_rready (axs_rready[0]),
        .s_rdata  (axs_rdata[0*64 +: 64]),
        .s_rresp  (axs_rresp[0*2 +: 2]),
        .s_awvalid(axs_awvalid[0]),
        .s_awready(axs_awready[0]),
        .s_awaddr (axs_awaddr[0*40 +: 40]),
        .s_awid   (axs_awid[0*4 +: 4]),
        .s_wvalid (axs_wvalid[0]),
        .s_wready (axs_wready[0]),
        .s_wdata  (axs_wdata[0*64 +: 64]),
        .s_wstrb  (axs_wstrb[0*8 +: 8]),
        .s_bvalid (axs_bvalid[0]),
        .s_bready (axs_bready[0]),
        .s_bresp  (axs_bresp[0*2 +: 2]),

        // Master face (to DDR controller)
        .m_arvalid(l2_m_arvalid),
        .m_arready(l2_m_arready),
        .m_araddr (l2_m_araddr),
        .m_rvalid (l2_m_rvalid),
        .m_rready (l2_m_rready),
        .m_rdata  (l2_m_rdata),
        .m_rresp  (l2_m_rresp),
        .m_awvalid(l2_m_awvalid),
        .m_awready(l2_m_awready),
        .m_awaddr (l2_m_awaddr),
        .m_wvalid (l2_m_wvalid),
        .m_wready (l2_m_wready),
        .m_wdata  (l2_m_wdata),
        .m_wstrb  (l2_m_wstrb),
        .m_bvalid (l2_m_bvalid),
        .m_bready (l2_m_bready),

        // L1 Snoop interfaces (Cores 0-3)
        .snoop_valid(l2_snoop_valid),
        .snoop_addr (l2_snoop_addr),
        .snoop_type (l2_snoop_type),
        .snoop_ack  (l2_snoop_ack),
        .snoop_data_valid(l2_snoop_data_valid),
        .snoop_data (l2_snoop_data_mux)
    );

    ddr_ctrl_top u_ddr_ctrl (
        .clk(clk), .rst_n(rst_n),
        .s_awvalid(l2_m_awvalid), .s_awready(l2_m_awready), .s_awaddr(l2_m_awaddr), 
        .s_awid(4'h0), .s_awlen(8'h0), .s_awsize(3'b011),
        .s_wvalid(l2_m_wvalid), .s_wready(l2_m_wready), .s_wdata(l2_m_wdata), 
        .s_wstrb(l2_m_wstrb), .s_wlast(1'b1),
        .s_bvalid(l2_m_bvalid), .s_bready(l2_m_bready), .s_bresp(l2_m_bresp), .s_bid(),
        
        .s_arvalid(l2_m_arvalid), .s_arready(l2_m_arready), .s_araddr(l2_m_araddr), 
        .s_arid(4'h0), .s_arlen(8'h0),
        .s_rvalid(l2_m_rvalid), .s_rready(l2_m_rready), .s_rdata(l2_m_rdata), 
        .s_rresp(l2_m_rresp), .s_rlast(), .s_rid(),
        
        .ddr_addr(ddr_addr), .ddr_ba(ddr_ba), .ddr_bg(ddr_bg),
        .ddr_ck_p(ddr_ck_p), .ddr_ck_n(ddr_ck_n), .ddr_cke(ddr_cke), .ddr_cs_n(ddr_cs_n),
        .ddr_ras_n(ddr_ras_n), .ddr_cas_n(ddr_cas_n), .ddr_we_n(ddr_we_n),
        .ddr_dq(ddr_dq), .ddr_dqs_p(ddr_dqs_p), .ddr_dqs_n(ddr_dqs_n)
    );

    // -------------------------------------------------------
    // AHB & APB Bridge (Slave 1)
    // -------------------------------------------------------
    wire [31:0] haddr, hwdata, hrdata;
    wire        hwrite, hready, hresp;
    wire [1:0]  htrans;
    wire [2:0]  hsize, hburst;

    axi4_to_ahb #(.AW(40), .DW(64), .IDW(4)) u_axi2ahb (
        .clk(clk), .rst_n(rst_n),
        .s_awvalid(axs_awvalid[1]), .s_awready(axs_awready[1]), .s_awaddr(axs_awaddr[1*40 +: 40]), .s_awid(axs_awid[1*4 +: 4]),
        .s_wvalid(axs_wvalid[1]),   .s_wready(axs_wready[1]),   .s_wdata(axs_wdata[1*64 +: 64]), .s_wstrb(axs_wstrb[1*8 +: 8]),
        .s_bvalid(axs_bvalid[1]),   .s_bready(axs_bready[1]),   .s_bresp(axs_bresp[1*2 +: 2]), .s_bid(axs_bid[1*4 +: 4]),
        .s_arvalid(axs_arvalid[1]), .s_arready(axs_arready[1]), .s_araddr(axs_araddr[1*40 +: 40]), .s_arid(axs_arid[1*4 +: 4]),
        .s_rvalid(axs_rvalid[1]),   .s_rready(axs_rready[1]),   .s_rdata(axs_rdata[1*64 +: 64]), .s_rresp(axs_rresp[1*2 +: 2]),
        .s_rlast(axs_rlast[1]),
        .haddr(haddr), .hwrite(hwrite), .htrans(htrans), .hsize(hsize), .hburst(hburst),
        .hwdata(hwdata), .hrdata(hrdata), .hready(hready), .hresp(hresp)
    );
    assign axs_rid[1*4 +: 4] = 4'h0;
    
    wire [31:0] paddr, pwdata;
    wire [63:0] prdata_mux;
    wire        psel, penable, pwrite;
    
    assign paddr = haddr;
    assign pwdata = hwdata[31:0];
    assign pwrite = hwrite;
    assign penable = htrans[1];
    assign psel = htrans[1];
    assign hrdata = prdata_mux[31:0];
    assign hready = 1'b1;
    assign hresp = 1'b0;

    // APB Address Decoder (supports 0x4000_0000 APB bridge window and legacy apertures)
    wire psel_uart0 = psel && (paddr[31:12] == 20'h40000 || paddr[31:12] == 20'h10000);
    wire psel_uart1 = psel && (paddr[31:12] == 20'h40001 || paddr[31:12] == 20'h10001);
    wire psel_uart2 = psel && (paddr[31:12] == 20'h40002 || paddr[31:12] == 20'h10002);
    wire psel_uart3 = psel && (paddr[31:12] == 20'h40003 || paddr[31:12] == 20'h10003);
    wire psel_uart4 = psel && (paddr[31:12] == 20'h40004 || paddr[31:12] == 20'h10004);
    wire psel_rtc   = psel && (paddr[31:12] == 20'h40010 || paddr[31:12] == 20'h10010);
    wire psel_gem   = psel && (paddr[31:12] == 20'h40020 || paddr[31:12] == 20'h10020);
    wire psel_usb   = psel && (paddr[31:12] == 20'h40030 || paddr[31:12] == 20'h10030);
    wire psel_mipi  = psel && (paddr[31:12] == 20'h40040 || paddr[31:12] == 20'h10040);
    wire psel_isp   = psel && (paddr[31:12] == 20'h40050 || paddr[31:12] == 20'h10050);
    wire psel_hdmi  = psel && (paddr[31:12] == 20'h40060 || paddr[31:12] == 20'h10060);
    wire psel_drbg  = psel && (paddr[31:12] == 20'h40070 || paddr[31:12] == 20'h20000);
    wire psel_aes   = psel && (paddr[31:12] == 20'h40080 || paddr[31:12] == 20'h20010);
    wire psel_envm  = psel && (paddr[31:12] == 20'h40090 || paddr[31:12] == 20'h20020);
    wire psel_boot  = psel && (paddr[31:12] == 20'h400A0 || paddr[31:12] == 20'h20030);
    wire psel_can0  = psel && (paddr[31:12] == 20'h400B0 || paddr[31:12] == 20'h30000);
    wire psel_can1  = psel && (paddr[31:12] == 20'h400C0 || paddr[31:12] == 20'h30001);
    wire psel_trng  = psel && (paddr[31:12] == 20'h400D0 || paddr[31:12] == 20'h20040);
    wire psel_sha256= psel && (paddr[31:12] == 20'h400E0 || paddr[31:12] == 20'h20050);
    wire psel_ecdsa = psel && (paddr[31:12] == 20'h400F0 || paddr[31:12] == 20'h20060);
    wire psel_clint = psel && (paddr[31:16] == 16'h0200 || paddr[31:12] == 20'h40015);
    wire psel_gpio  = psel && (paddr[31:12] == 20'h40011);
    wire psel_wdt   = psel && (paddr[31:12] == 20'h40012);
    wire psel_spi   = psel && (paddr[31:12] == 20'h40013);
    wire psel_i2c   = psel && (paddr[31:12] == 20'h40014);
    wire psel_mmc   = psel && (paddr[31:12] == 20'h40016);
    wire psel_qspi  = psel && (paddr[31:12] == 20'h40017);
    wire psel_vdma  = psel && (paddr[31:12] == 20'h40018);
    assign psel_mpu = psel && (paddr[31:16] == 16'h4010);
    assign psel_qos = psel && (paddr[31:16] == 16'h4011);
    assign psel_plic = psel && (paddr[31:24] == 8'h0C || paddr[31:20] == 12'h40D);

    wire [31:0] prdata_uart0, prdata_uart1, prdata_uart2, prdata_uart3, prdata_uart4;
    wire [31:0] prdata_rtc, prdata_gem, prdata_usb, prdata_mipi, prdata_isp, prdata_hdmi;
    wire [31:0] prdata_drbg, prdata_aes, prdata_envm, prdata_boot, prdata_can0, prdata_can1;
    wire [31:0] prdata_trng, prdata_sha256, prdata_ecdsa;
    wire [31:0] prdata_clint, prdata_gpio, prdata_wdt, prdata_spi, prdata_i2c;
    wire [31:0] prdata_mmc, prdata_qspi, prdata_vdma;

    assign prdata_mux = psel_uart0  ? {32'h0, prdata_uart0} :
                        psel_uart1  ? {32'h0, prdata_uart1} :
                        psel_uart2  ? {32'h0, prdata_uart2} :
                        psel_uart3  ? {32'h0, prdata_uart3} :
                        psel_uart4  ? {32'h0, prdata_uart4} :
                        psel_rtc    ? {32'h0, prdata_rtc} :
                        psel_clint  ? {32'h0, prdata_clint} :
                        psel_gpio   ? {32'h0, prdata_gpio} :
                        psel_wdt    ? {32'h0, prdata_wdt} :
                        psel_spi    ? {32'h0, prdata_spi} :
                        psel_i2c    ? {32'h0, prdata_i2c} :
                        psel_mmc    ? {32'h0, prdata_mmc} :
                        psel_qspi   ? {32'h0, prdata_qspi} :
                        psel_vdma   ? {32'h0, prdata_vdma} :
                        psel_gem    ? {32'h0, prdata_gem} :
                        psel_usb    ? {32'h0, prdata_usb} :
                        psel_mipi   ? {32'h0, prdata_mipi} :
                        psel_isp    ? {32'h0, prdata_isp} :
                        psel_hdmi   ? {32'h0, prdata_hdmi} :
                        psel_drbg   ? {32'h0, prdata_drbg} :
                        psel_aes    ? {32'h0, prdata_aes} :
                        psel_envm   ? {32'h0, prdata_envm} :
                        psel_boot   ? {32'h0, prdata_boot} :
                        psel_can0   ? {32'h0, prdata_can0} :
                        psel_can1   ? {32'h0, prdata_can1} :
                        psel_trng   ? {32'h0, prdata_trng} :
                        psel_sha256 ? {32'h0, prdata_sha256} :
                        psel_ecdsa  ? {32'h0, prdata_ecdsa} :
                        psel_mpu    ? {32'h0, prdata_mpu} :
                        psel_qos    ? {32'h0, prdata_qos} :
                        psel_plic   ? {32'h0, prdata_plic} : 64'h0;

    // -------------------------------------------------------
    // DMA Peripherals (Masters 10, 11, 12, 13, 14)
    // -------------------------------------------------------
    wire [7:0] safe_gmii_rxd   = (gmii_rxd === 8'hxx || gmii_rxd === 8'hzz) ? 8'h0 : gmii_rxd;
    wire       safe_gmii_rx_dv = (gmii_rx_dv === 1'bx || gmii_rx_dv === 1'bz) ? 1'b0 : gmii_rx_dv;
    wire       safe_gmii_rx_er = (gmii_rx_er === 1'bx || gmii_rx_er === 1'bz) ? 1'b0 : gmii_rx_er;
    wire       safe_gmii_crs   = (gmii_crs === 1'bx || gmii_crs === 1'bz) ? 1'b0 : gmii_crs;
    wire       safe_gmii_col   = (gmii_col === 1'bx || gmii_col === 1'bz) ? 1'b0 : gmii_col;

    gem_ethernet u_gem (
        .clk(clk), .rst_n(rst_n), .tx_clk(eth_tx_clk), .rx_clk(eth_rx_clk),
        .m_awvalid(axm_awvalid[10]), .m_awready(axm_awready[10]), .m_awaddr(axm_awaddr[10*40 +: 40]), .m_awid(axm_awid[10*4 +: 4]),
        .m_wvalid(axm_wvalid[10]),   .m_wready(axm_wready[10]),   .m_wdata(axm_wdata[10*64 +: 64]),   .m_wstrb(axm_wstrb[10*8 +: 8]), .m_wlast(axm_wlast[10]),
        .m_bvalid(axm_bvalid[10]),   .m_bready(axm_bready[10]),   .m_bresp(axm_bresp[10*2 +: 2]),     .m_bid(axm_bid[10*4 +: 4]),
        .m_arvalid(axm_arvalid[10]), .m_arready(axm_arready[10]), .m_araddr(axm_araddr[10*40 +: 40]), .m_arid(axm_arid[10*4 +: 4]),
        .m_rvalid(axm_rvalid[10]),   .m_rready(axm_rready[10]),   .m_rdata(axm_rdata[10*64 +: 64]),   .m_rresp(axm_rresp[10*2 +: 2]), .m_rlast(axm_rlast[10]),
        .paddr(paddr), .psel(psel_gem), .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .prdata(prdata_gem), .pready(), .pslverr(),
        .mac_irq(plic_irq[27]),
        .gmii_txd(gmii_txd), .gmii_tx_en(gmii_tx_en), .gmii_tx_er(gmii_tx_er),
        .gmii_rxd(safe_gmii_rxd), .gmii_rx_dv(safe_gmii_rx_dv), .gmii_rx_er(safe_gmii_rx_er),
        .gmii_crs(safe_gmii_crs), .gmii_col(safe_gmii_col)
    );

    wire [63:0] safe_pipe_rx_data     = (pipe_rx_data === 64'hxx || pipe_rx_data === 64'hzz) ? 64'h0 : pipe_rx_data;
